export interface RetryOptions {
  retries: number;
  delayMs: number;
  signal?: AbortSignal;
}

/** Retry an async operation with a fixed delay between attempts, honoring `signal`. */
export async function retry<T>(fn: () => Promise<T>, opts: RetryOptions): Promise<T> {
  let attempt = 0;
  for (;;) {
    if (opts.signal?.aborted) throw new Error("retry aborted");
    try {
      return await fn();
    } catch (err) {
      attempt += 1;
      if (attempt >= opts.retries) throw err;
      await new Promise<void>((resolve, reject) => {
        const timer = setTimeout(resolve, opts.delayMs);
        opts.signal?.addEventListener(
          "abort",
          () => {
            clearTimeout(timer);
            reject(new Error("retry aborted"));
          },
          { once: true },
        );
      });
    }
  }
}

import assert from "node:assert/strict";
import test from "node:test";
import { retry } from "./retry.ts";

test("retries until success", async () => {
  let calls = 0;
  const result = await retry(
    async () => {
      calls += 1;
      if (calls < 3) throw new Error("not yet");
      return "ok";
    },
    { retries: 5, delayMs: 1 },
  );
  assert.equal(result, "ok");
  assert.equal(calls, 3);
});

test("stops retrying once the signal is aborted", async () => {
  const controller = new AbortController();
  const attempt = retry(
    async () => {
      throw new Error("still failing");
    },
    { retries: 10, delayMs: 50, signal: controller.signal },
  );
  controller.abort();
  await assert.rejects(attempt, /retry aborted/);
});
